/* ============================================================
   TUSHAL KUMAR PORTFOLIO — app.js
   ============================================================ */

/* ── ASSETS (embedded — works offline & on any host) ──────── */
const PHOTO_B64  = 'https://i.postimg.cc/43g415VF/profile.jpg';
const RESUME_B64 = '';

/* ── 0. INJECT PHOTO ───────────────────────────────────────── */
(function () {
  const img = document.getElementById('heroPhoto');
  if (!img) return;
  img.src = PHOTO_B64;
  img.addEventListener('error', () => {
    // If the hosted photo ever fails to load, hide the empty box
    // instead of showing a broken-image icon.
    img.closest('.portrait-img')?.classList.add('portrait-img--empty');
  });
})();


/* ── 1. THEME TOGGLE ───────────────────────────────────────── */
const html        = document.documentElement;
const themeToggle = document.getElementById('themeToggle');
html.setAttribute('data-theme', localStorage.getItem('tk-theme') || 'light');
themeToggle.addEventListener('click', () => {
  const next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  html.setAttribute('data-theme', next);
  localStorage.setItem('tk-theme', next);
});


/* ── 2. RESUME DOWNLOAD (base64 embedded — always works) ───── */
document.getElementById('resumeDownload').addEventListener('click', e => {
  // No embedded PDF available -> let the normal <a download> link work
  if (typeof RESUME_B64 === 'undefined') return;
  e.preventDefault();
  // Build a real PDF blob from the embedded base64 and trigger download
  const bytes  = atob(RESUME_B64);
  const buffer = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) buffer[i] = bytes.charCodeAt(i);
  const blob = new Blob([buffer], { type: 'application/pdf' });
  const url  = URL.createObjectURL(blob);
  const a    = Object.assign(document.createElement('a'), {
    href:     url,
    download: 'TushalKumar_Resume.pdf',
  });
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 5000);
});


/* ── 3. SMOOTH SCROLL ──────────────────────────────────────── */
document.addEventListener('click', e => {
  const a = e.target.closest('a[href^="#"]');
  if (!a) return;
  const id = a.getAttribute('href').slice(1);
  if (!id) return;
  const target = document.getElementById(id);
  if (!target) return;
  e.preventDefault();
  window.scrollTo({ top: target.getBoundingClientRect().top + window.scrollY - 80, behavior: 'smooth' });
  document.getElementById('navMobile').classList.remove('open');
});


/* ── 4. NAVBAR SCROLL + ACTIVE LINK ────────────────────────── */
const navbar   = document.getElementById('navbar');
const navLinks = document.querySelectorAll('.nav-link');

function onScroll() {
  navbar.classList.toggle('scrolled', window.scrollY > 50);
  // Active link
  let current = '';
  document.querySelectorAll('section[id]').forEach(s => {
    if (window.scrollY >= s.offsetTop - 130) current = s.id;
  });
  navLinks.forEach(l => l.classList.toggle('active', l.getAttribute('href') === '#' + current));
  // Back-to-top
  document.getElementById('backToTop').classList.toggle('visible', window.scrollY > 400);
}

window.addEventListener('scroll', onScroll, { passive: true });


/* ── 5. MOBILE NAV TOGGLE ──────────────────────────────────── */
document.getElementById('navToggle').addEventListener('click', () => {
  document.getElementById('navMobile').classList.toggle('open');
});


/* ── 6. TYPEWRITER ─────────────────────────────────────────── */
const typewriterEl = document.getElementById('typewriter');
const phrases = ['CS Student', 'Java Developer', 'AI Enthusiast', 'Problem Solver', 'Software Engineer'];
let pi = 0, ci = 0, del = false;
function type() {
  const phrase = phrases[pi];
  typewriterEl.textContent = phrase.slice(0, ci);
  if (!del) {
    if (++ci > phrase.length) { del = true; setTimeout(type, 1800); return; }
  } else {
    if (--ci < 0) { del = false; ci = 0; pi = (pi + 1) % phrases.length; setTimeout(type, 400); return; }
  }
  setTimeout(type, del ? 55 : 90);
}
setTimeout(type, 800);


/* ── 7. SCROLL REVEAL ──────────────────────────────────────── */
const revealObs = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('revealed'); revealObs.unobserve(e.target); } });
}, { threshold: 0.12, rootMargin: '0px 0px -60px 0px' });
document.querySelectorAll('.reveal-up,.reveal-left,.reveal-right').forEach(el => revealObs.observe(el));


/* ── 8. ANIMATED COUNTERS ──────────────────────────────────── */
const cntObs = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) { animateCounter(e.target); cntObs.unobserve(e.target); } });
}, { threshold: 0.5 });
document.querySelectorAll('.stat-num[data-count]').forEach(el => cntObs.observe(el));
function animateCounter(el) {
  const target = +el.dataset.count, suffix = el.dataset.suffix || '', t0 = performance.now();
  (function step(now) {
    const p = Math.min((now - t0) / 1600, 1);
    el.textContent = Math.round((1 - Math.pow(1 - p, 3)) * target) + suffix;
    if (p < 1) requestAnimationFrame(step);
  })(t0);
}


/* ── 9. SKILL PROGRESS BARS ────────────────────────────────── */
const progObs = new IntersectionObserver(entries => {
  entries.forEach(e => {
    if (e.isIntersecting) { setTimeout(() => { e.target.style.width = e.target.dataset.w + '%'; }, 200); progObs.unobserve(e.target); }
  });
}, { threshold: 0.3 });
document.querySelectorAll('.prog-bar[data-w]').forEach(b => progObs.observe(b));


/* ── 10. PROJECT FILTER ────────────────────────────────────── */
document.head.insertAdjacentHTML('beforeend',
  '<style>@keyframes fadeIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}</style>');
document.querySelectorAll('.filter-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
    document.querySelectorAll('.project-card').forEach(card => {
      const show = btn.dataset.filter === 'All' || card.dataset.cat === btn.dataset.filter;
      card.classList.toggle('hidden', !show);
      if (show) card.style.animation = 'fadeIn 0.4s ease forwards';
    });
  });
});


/* ── 11. CONTACT FORM (Formspree) ──────────────────────────── */
const contactForm = document.getElementById('contactForm');
const sendBtn     = document.getElementById('sendBtn');
const formMsg     = document.getElementById('formMsg');

contactForm.addEventListener('submit', async e => {
  e.preventDefault();
  sendBtn.disabled = true;
  sendBtn.textContent = 'Sending…';
  formMsg.textContent = '';
  formMsg.className = 'form-feedback';

  try {
    const res = await fetch(contactForm.action, {
      method: 'POST',
      body: new FormData(contactForm),
      headers: { 'Accept': 'application/json' }
    });
    if (res.ok) {
      formMsg.textContent = '✓ Message sent! I\'ll get back to you soon.';
      formMsg.className = 'form-feedback success';
      contactForm.reset();
      sendBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg> Sent!`;
      sendBtn.style.background = 'linear-gradient(135deg,#10b981,#059669)';
      setTimeout(() => {
        sendBtn.disabled = false;
        sendBtn.style.background = '';
        sendBtn.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/></svg> Send Message`;
      }, 4000);
    } else {
      throw new Error();
    }
  } catch {
    formMsg.textContent = '✗ Something went wrong. Email me directly at tushalkumardawani.official111@gmail.com';
    formMsg.className = 'form-feedback error';
    sendBtn.disabled = false;
    sendBtn.textContent = 'Try Again';
  }
});


/* ── 12. BACK TO TOP ───────────────────────────────────────── */
document.getElementById('backToTop').addEventListener('click', () =>
  window.scrollTo({ top: 0, behavior: 'smooth' })
);


/* ── 13. FOOTER YEAR ───────────────────────────────────────── */
document.getElementById('yr').textContent = new Date().getFullYear();


/* ── 14. CURSOR GLOW (desktop) ─────────────────────────────── */
if (window.matchMedia('(pointer: fine)').matches) {
  const glow = document.createElement('div');
  Object.assign(glow.style, {
    position: 'fixed', width: '28rem', height: '28rem', borderRadius: '50%',
    background: 'radial-gradient(circle,rgba(128,128,128,0.12) 0%,transparent 70%)',
    pointerEvents: 'none', transform: 'translate(-50%,-50%)', zIndex: '0',
    transition: 'left .15s ease,top .15s ease',
  });
  document.body.appendChild(glow);
  window.addEventListener('mousemove', e => {
    glow.style.left = e.clientX + 'px';
    glow.style.top  = e.clientY + 'px';
  }, { passive: true });
}


/* ── INIT ──────────────────────────────────────────────────── */
onScroll();

/* ── 15. EXPERIENCE TIMELINE PROGRESS ──────────────────────── */
(function () {
  const tl = document.getElementById('expTimeline');
  if (!tl) return;
  const nodes = tl.querySelectorAll('.exp-node');
  function update() {
    const r = tl.getBoundingClientRect();
    const trigger = window.innerHeight * 0.6;
    const p = Math.min(Math.max((trigger - r.top) / r.height, 0), 1);
    tl.style.setProperty('--exp-progress', (p * 100) + '%');
    nodes.forEach(n => n.classList.toggle('active', n.getBoundingClientRect().top < trigger));
  }
  window.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', update);
  update();
})();


/* ── 16. HERO PHOTO: AUTO CUT-OUT ──────────────────────────────
   Makes a plain photo background transparent so the portrait sits
   directly on the black panel. Tweak PHOTO_TOLERANCE (20–80):
   higher removes more of the background, lower keeps more.
   A photo that already has a transparent background is left as is. */
(function () {
  const PHOTO_TOLERANCE = 46;
  const img = document.getElementById('heroPhoto');
  if (!img) return;
  const box = img.closest('.portrait-img');
  const src = typeof PHOTO_B64 !== 'undefined' ? PHOTO_B64 : img.src;
  if (!src) return;

  const probe = new Image();
  probe.crossOrigin = 'anonymous';
  probe.onerror = () => box && box.classList.add('is-boxed');
  probe.onload = () => {
    try {
      const s = Math.min(1, 900 / probe.naturalWidth);
      const w = Math.round(probe.naturalWidth * s), h = Math.round(probe.naturalHeight * s);
      const c = document.createElement('canvas'); c.width = w; c.height = h;
      const ctx = c.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(probe, 0, 0, w, h);
      const d = ctx.getImageData(0, 0, w, h), px = d.data;

      // average colour of the four corners = background
      const k = Math.max(4, Math.round(w * 0.02));
      let r = 0, g = 0, b = 0, a = 0, n = 0;
      [[0, 0], [w - k, 0], [0, h - k], [w - k, h - k]].forEach(([x0, y0]) => {
        for (let y = y0; y < y0 + k; y++) for (let x = x0; x < x0 + k; x++) {
          const i = (y * w + x) * 4; r += px[i]; g += px[i + 1]; b += px[i + 2]; a += px[i + 3]; n++;
        }
      });
      r /= n; g /= n; b /= n; a /= n;
      if (a < 20) { box && box.classList.add('is-cutout'); return; }   // already transparent

      // flood-fill from the edges through pixels close to the background colour
      const seen = new Uint8Array(w * h), stack = [];
      const near = p => { const i = p * 4;
        return Math.hypot(px[i] - r, px[i + 1] - g, px[i + 2] - b) < PHOTO_TOLERANCE; };
      const push = p => { if (!seen[p] && near(p)) { seen[p] = 1; stack.push(p); } };
      for (let x = 0; x < w; x++) { push(x); push((h - 1) * w + x); }
      for (let y = 0; y < h; y++) { push(y * w); push(y * w + w - 1); }
      while (stack.length) {
        const p = stack.pop(), x = p % w, y = (p / w) | 0;
        if (x > 0) push(p - 1); if (x < w - 1) push(p + 1);
        if (y > 0) push(p - w); if (y < h - 1) push(p + w);
      }
      for (let p = 0; p < w * h; p++) if (seen[p]) px[p * 4 + 3] = 0;
      // soften the cut edge by one pixel
      for (let y = 1; y < h - 1; y++) for (let x = 1; x < w - 1; x++) {
        const p = y * w + x;
        if (!seen[p] && (seen[p - 1] || seen[p + 1] || seen[p - w] || seen[p + w])) px[p * 4 + 3] = 140;
      }
      ctx.putImageData(d, 0, 0);
      img.src = c.toDataURL('image/png');
      box && box.classList.add('is-cutout');
    } catch (err) {
      box && box.classList.add('is-boxed');   // canvas blocked: fall back to a soft bottom fade
    }
  };
  probe.src = src;
})();
